import { BooleanColumn, StringColumn, IntegerColumn, ChoiceColumn } from '@servicenow/sdk/core'
import { ActionDefinition, FlowObject, FlowArray } from '@servicenow/sdk/automation'

/**
 * Example 5: Action definition with nested FlowArray containing FlowObject elements
 *
 * This demonstrates a FlowArray that contains FlowObject elements.
 */

ActionDefinition({
    $id: Now.ID['action-nested-array-with-object'],
    name: 'fl-action-nested-array-with-object',
    annotation: 'Test action with nested FlowArray containing FlowObjects',
    description: 'Demonstrates nested FlowArray with FlowObject elements',
    category: 'Testing',
    inputs: {
        teamMembers: FlowArray({
            label: 'Team Members',
            mandatory: false,
            childName: 'team_member_child0',
            elementType: FlowObject({
                label: 'Team Member',
                fields: {
                    name: StringColumn({
                        label: 'Name',
                        mandatory: true,
                        maxLength: 100,
                    }),
                    role: ChoiceColumn({
                        label: 'Role',
                        mandatory: true,
                        choices: {
                            developer: 'Developer',
                            designer: 'Designer',
                            product_manager: 'Product Manager',
                            qa: 'QA Engineer',
                        },
                    }),
                    yearsOfExperience: IntegerColumn({
                        label: 'Years of Experience',
                        mandatory: false,
                        min: 0,
                    }),
                },
            }),
        }),
    },
    outputs: {
        success: BooleanColumn({
            label: 'Success',
            mandatory: true,
        }),

        // Output with nested FlowArray containing FlowObjects
        assignedTasks: FlowArray({
            label: 'Assigned Tasks',
            mandatory: false,
            childName: 'task_assignment_child0',
            elementType: FlowObject({
                label: 'Task Assignment',
                fields: {
                    taskId: StringColumn({
                        label: 'Task ID',
                        mandatory: true,
                    }),
                    assigneeName: StringColumn({
                        label: 'Assignee Name',
                        mandatory: true,
                    }),
                    dueDate: StringColumn({
                        label: 'Due Date',
                        mandatory: false,
                    }),
                },
            }),
        }),
    },
})
